permission_denials.command:
python3 -c "
import re, sys
try:
    import yaml
except ImportError:
    print('no pyyaml'); sys.exit(0)
try:
    import jsonschema
except ImportError:
    jsonschema = None

text = open('journals/2026-08-18-product-3-500s.md').read()
m = re.match(r'^---\n(.*?)\n---\n', text, re.S)
fm = yaml.safe_load(m.group(1))
print('parsed ok, keys:', list(fm.keys()))

import json
schema = json.load(open('.claude/skills/investigate/journal.schema.json'))
if jsonschema:
    jsonschema.validate(fm, schema)
    print('SCHEMA VALID')
else:
    print('no jsonschema module, skipped strict validation')

# manual referential checks
ev_ids = {e['id'] for e in fm['evidence']}
for h in fm['hypotheses']:
    for r in h['evidence_for'] + h['evidence_against']:
        assert r in ev_ids, f'missing {r}'
print('all evidence refs resolve')
print('wall_clock check:', fm['investigation']['started'], fm['investigation']['concluded'], fm['usage']['wall_clock_seconds'])
"
